-- Domain tables for repositories, campaigns, agent work, verification,
-- activity and migration patterns.
--
-- Conventions:
--   * Entity ids are UUID v4 strings generated by the application.
--   * Timestamps are UTC RFC 3339 with millisecond precision ("...T...123Z").
--   * *_json columns hold JSON validated by the application before writing.
--   * Enumerations are enforced with CHECK constraints.
--   * Deleting a repository record never touches files on disk.

CREATE TABLE repositories (
    id TEXT PRIMARY KEY NOT NULL,
    source_type TEXT NOT NULL CHECK (source_type IN ('local', 'github')),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 255),
    local_path TEXT,
    remote_url TEXT,
    github_host TEXT COLLATE NOCASE,
    github_owner TEXT COLLATE NOCASE,
    github_repo TEXT COLLATE NOCASE,
    default_branch TEXT,
    current_branch TEXT,
    current_commit TEXT,
    trust_status TEXT NOT NULL DEFAULT 'untrusted' CHECK (trust_status IN ('untrusted', 'trusted', 'blocked')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CHECK (source_type <> 'local' OR local_path IS NOT NULL),
    CHECK (source_type <> 'github' OR github_host IS NOT NULL),
    CHECK ((github_host IS NULL AND github_owner IS NULL AND github_repo IS NULL)
        OR (github_host IS NOT NULL AND github_owner IS NOT NULL AND github_repo IS NOT NULL))
);
CREATE UNIQUE INDEX repositories_local_path_uq ON repositories (local_path) WHERE local_path IS NOT NULL;
CREATE UNIQUE INDEX repositories_github_uq ON repositories (github_host, github_owner, github_repo)
    WHERE github_host IS NOT NULL;
CREATE INDEX repositories_trust_idx ON repositories (trust_status, name);
CREATE INDEX repositories_updated_idx ON repositories (updated_at DESC);

CREATE TABLE repository_scans (
    id TEXT PRIMARY KEY NOT NULL,
    repository_id TEXT NOT NULL REFERENCES repositories (id) ON DELETE CASCADE,
    scanned_commit TEXT,
    relevant_files_hash TEXT,
    status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed', 'cancelled')),
    result_json TEXT,
    error_code TEXT,
    error_message TEXT,
    started_at TEXT NOT NULL,
    completed_at TEXT,
    CHECK (status IN ('queued', 'running') OR completed_at IS NOT NULL)
);
CREATE INDEX repository_scans_repository_idx ON repository_scans (repository_id, started_at DESC);
CREATE INDEX repository_scans_status_idx ON repository_scans (status);

CREATE TABLE repository_dependencies (
    id TEXT PRIMARY KEY NOT NULL,
    source_repository_id TEXT NOT NULL REFERENCES repositories (id) ON DELETE CASCADE,
    target_repository_id TEXT NOT NULL REFERENCES repositories (id) ON DELETE CASCADE,
    relationship_type TEXT NOT NULL CHECK (length(relationship_type) BETWEEN 1 AND 64),
    confidence REAL NOT NULL CHECK (confidence >= 0 AND confidence <= 1),
    evidence_json TEXT NOT NULL DEFAULT '[]',
    detection_method TEXT NOT NULL,
    confirmation_status TEXT NOT NULL DEFAULT 'inferred'
        CHECK (confirmation_status IN ('inferred', 'confirmed', 'rejected')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CHECK (source_repository_id <> target_repository_id),
    UNIQUE (source_repository_id, target_repository_id, relationship_type)
);
CREATE INDEX repository_dependencies_target_idx ON repository_dependencies (target_repository_id);

CREATE TABLE campaigns (
    id TEXT PRIMARY KEY NOT NULL,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    objective TEXT NOT NULL,
    migration_type TEXT NOT NULL,
    source_condition_json TEXT NOT NULL DEFAULT '{}',
    target_condition_json TEXT NOT NULL DEFAULT '{}',
    constraints_json TEXT NOT NULL DEFAULT '{}',
    verification_profile TEXT NOT NULL,
    maximum_parallel_tasks INTEGER NOT NULL DEFAULT 1 CHECK (maximum_parallel_tasks BETWEEN 1 AND 100),
    status TEXT NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'planning', 'ready', 'running', 'paused', 'completed', 'failed', 'cancelled')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX campaigns_status_idx ON campaigns (status, updated_at DESC);
CREATE INDEX campaigns_updated_idx ON campaigns (updated_at DESC);

-- Repositories cannot be removed while they belong to a campaign (RESTRICT);
-- deleting a campaign removes its membership rows (CASCADE) unless agent work
-- references them.
CREATE TABLE campaign_repositories (
    id TEXT PRIMARY KEY NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns (id) ON DELETE CASCADE,
    repository_id TEXT NOT NULL REFERENCES repositories (id) ON DELETE RESTRICT,
    classification TEXT NOT NULL DEFAULT 'unclassified'
        CHECK (classification IN ('unclassified', 'affected', 'not_affected', 'needs_review')),
    risk_score REAL CHECK (risk_score IS NULL OR (risk_score >= 0 AND risk_score <= 1)),
    risk_explanation_json TEXT NOT NULL DEFAULT '[]',
    wave_number INTEGER CHECK (wave_number IS NULL OR wave_number >= 0),
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'excluded', 'queued', 'in_progress', 'awaiting_verification', 'verified', 'failed', 'blocked')),
    exclusion_reason TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE (campaign_id, repository_id),
    CHECK (status <> 'excluded' OR exclusion_reason IS NOT NULL)
);
CREATE INDEX campaign_repositories_repository_idx ON campaign_repositories (repository_id);
CREATE INDEX campaign_repositories_status_idx ON campaign_repositories (campaign_id, status, wave_number);

CREATE TABLE agent_tasks (
    id TEXT PRIMARY KEY NOT NULL,
    campaign_repository_id TEXT NOT NULL REFERENCES campaign_repositories (id) ON DELETE RESTRICT,
    provider TEXT NOT NULL CHECK (provider IN ('devin')),
    execution_mode TEXT NOT NULL CHECK (execution_mode IN ('cloud_session', 'local_cli')),
    instructions_markdown TEXT NOT NULL,
    external_session_id TEXT,
    external_session_url TEXT,
    worktree_path TEXT,
    branch_name TEXT,
    commit_sha TEXT,
    pull_request_url TEXT,
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'queued', 'running', 'awaiting_review', 'completed', 'failed', 'cancelled')),
    started_at TEXT,
    completed_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX agent_tasks_campaign_repository_idx ON agent_tasks (campaign_repository_id);
CREATE INDEX agent_tasks_status_idx ON agent_tasks (status, updated_at DESC);
CREATE UNIQUE INDEX agent_tasks_external_session_uq ON agent_tasks (provider, external_session_id)
    WHERE external_session_id IS NOT NULL;

CREATE TABLE agent_runs (
    id TEXT PRIMARY KEY NOT NULL,
    agent_task_id TEXT NOT NULL REFERENCES agent_tasks (id) ON DELETE CASCADE,
    provider TEXT NOT NULL,
    process_id INTEGER,
    external_run_id TEXT,
    status TEXT NOT NULL CHECK (status IN ('starting', 'running', 'succeeded', 'failed', 'cancelled', 'timed_out')),
    exit_code INTEGER,
    started_at TEXT NOT NULL,
    completed_at TEXT,
    redacted_output_path TEXT,
    error_json TEXT
);
CREATE INDEX agent_runs_task_idx ON agent_runs (agent_task_id, started_at DESC);
CREATE INDEX agent_runs_status_idx ON agent_runs (status);

CREATE TABLE verification_runs (
    id TEXT PRIMARY KEY NOT NULL,
    campaign_repository_id TEXT NOT NULL REFERENCES campaign_repositories (id) ON DELETE RESTRICT,
    agent_task_id TEXT REFERENCES agent_tasks (id) ON DELETE SET NULL,
    profile TEXT NOT NULL,
    verified_commit_sha TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'passed', 'failed', 'error', 'cancelled')),
    started_at TEXT NOT NULL,
    completed_at TEXT,
    summary_json TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX verification_runs_campaign_repository_idx ON verification_runs (campaign_repository_id, started_at DESC);
CREATE INDEX verification_runs_status_idx ON verification_runs (status, started_at DESC);
CREATE INDEX verification_runs_task_idx ON verification_runs (agent_task_id);

CREATE TABLE verification_checks (
    id TEXT PRIMARY KEY NOT NULL,
    verification_run_id TEXT NOT NULL REFERENCES verification_runs (id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    category TEXT NOT NULL
        CHECK (category IN ('install', 'build', 'test', 'lint', 'typecheck', 'security', 'custom')),
    command_json TEXT,
    status TEXT NOT NULL
        CHECK (status IN ('pending', 'running', 'passed', 'failed', 'skipped', 'error', 'cancelled')),
    exit_code INTEGER,
    duration_ms INTEGER CHECK (duration_ms IS NULL OR duration_ms >= 0),
    redacted_output TEXT,
    evidence_json TEXT,
    suggested_action TEXT,
    started_at TEXT NOT NULL,
    completed_at TEXT
);
CREATE INDEX verification_checks_run_idx ON verification_checks (verification_run_id, started_at);

CREATE TABLE activity_events (
    id TEXT PRIMARY KEY NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id TEXT,
    event_type TEXT NOT NULL,
    severity TEXT NOT NULL CHECK (severity IN ('info', 'notice', 'warning', 'error')),
    summary TEXT NOT NULL,
    metadata_json TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL
);
-- Reverse-chronological retrieval; rowid breaks ties within a millisecond.
CREATE INDEX activity_events_created_idx ON activity_events (created_at DESC);
CREATE INDEX activity_events_entity_idx ON activity_events (entity_type, entity_id, created_at DESC);
CREATE INDEX activity_events_severity_idx ON activity_events (severity, created_at DESC);

CREATE TABLE migration_patterns (
    id TEXT PRIMARY KEY NOT NULL,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    applicability_json TEXT NOT NULL DEFAULT '{}',
    problem_description TEXT NOT NULL,
    solution_markdown TEXT NOT NULL,
    verification_rules_json TEXT NOT NULL DEFAULT '[]',
    confidence REAL NOT NULL CHECK (confidence >= 0 AND confidence <= 1),
    approval_status TEXT NOT NULL DEFAULT 'candidate'
        CHECK (approval_status IN ('candidate', 'approved', 'rejected', 'disabled')),
    source_campaign_id TEXT REFERENCES campaigns (id) ON DELETE SET NULL,
    source_repository_id TEXT REFERENCES repositories (id) ON DELETE SET NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX migration_patterns_status_idx ON migration_patterns (approval_status, updated_at DESC);
